def above_mean(xs):
    if not xs:
        return 0
    total, n = sum(xs), len(xs)
    return sum(1 for x in xs if x * n > total)

def settle_day(trade_day, lag, holidays):
    day, left = trade_day, lag
    while left > 0:
        day += 1
        if day % 7 < 5 and day not in holidays:
            left -= 1
    return day

def rows_needed(target):
    lo, hi = 0, 2 * 10**9
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * (mid + 1) // 2 >= target:
            hi = mid
        else:
            lo = mid + 1
    return lo

def dice_ways(n, total):
    if total < 0:
        return 0
    ways = [1] + [0] * total
    for _ in range(n):
        new = [0] * (total + 1)
        for t in range(1, total + 1):
            new[t] = sum(ways[t - f] for f in range(1, 7) if t - f >= 0)
        ways = new
    return ways[total]

